G.texts[#G.texts+1] = { p="thewarchiefhasinstructedmetostudyallkind", s="thequilboarorcentaur", t="Warchief надад бүх төрлийн зэвсэг, хуяг судлахыг даалгасан. Тэр намайг Barrens дахь tauren болон orc соёлын төв болох энд аль болох олон аялагчтай уулзаж, Barrens-ын соёлуудыг судлахаар илгээсэн.$B$BТэр хамгийн өрөвдөлтэй соёлуудаас ч гэсэн сурах зүйл байдаг гэж үздэг... quilboar эсвэл centaur шиг." }
G.texts[#G.texts+1] = { p="you", s="umusthelpmangletooth", t="Чи! $R! Наашаа ир. <snort>$B$BЦаг богино, миний төгсгөл <snort> ойрхон байна. Mangletooth ялна; чи харна. <snort>$B$BМиний олзлогдол ард түмэнд минь <snort> одоо ч тус болж чадна. Razormane омог Bristleback-уудаас илүү хүчтэй!$B$BHorde өөрсдийн ард түмэн рүү дайрдаг хэн болохыг олж мэдэх гэж байна. Чи <snort> зөвхөн миний мэддэг мэдээллийн хариуд Mangletooth-д тусална. Mangletooth чамд тусалж чадна! <snort> Харин чи Mangletooth-д туслах ёстой." }
G.texts[#G.texts+1] = { p="myhatredisstrongsnortbutthetimeisrightto", s="thecavernstothesouth", t="Миний үзэн ядалт хүчтэй <snort>, гэхдээ чамд нэгэн түүх ярих цаг иржээ, $r.$B$BУдаан жилийн өмнө бурхад хооронд тулалдаан болсон. Манай агуу гахай бурхан Agamaggan Эртний Хүмүүсийн Дайнд ялагдаж, дэлхийд унаж, цус нь бороо мэт асгарч, яс нь тасарч хэмхэрсэн. <snort>$B$BТүүний цус газарт хүрсэн газарт агуу өргөстэй ургамал газраас дээш өргөгдөж, гавлын яс нь өмнөд зүгийн нэг агуйг чимдэг." }
G.texts[#G.texts+1] = { p="youhavesnortaidedmangletoothmorethaniwou", s="uwithagamagganspower", t="Чи <snort> Mangletooth-д миний мөрөөдөж байснаас ч илүү тусаллаа, $r.$B$BБаярлалаа.$B$BБи энд олзлогдсон хэвээр байх хугацаанд чи Bristleback quilboar-уудын цусан үлдэгдлийг надад авчирч болно, би чамайг Agamaggan-ы хүчээр ивээх болно." }
