G.texts[#G.texts+1] = { p="allmembersofthehordeareequalinmyeyes", s="darmywholackfreewill", t="Horde-ийн бүх гишүүд миний нүдэнд адил тэгш, $N. Бид бүгд олон дарамт зовлон туулсан, хэрэв мэргэн ухаан, нэр төр байгаагүй бол бид Scourge-ээс ч, эсвэл миний ард түмэн Mannoroth чөтгөрөөр цус нь бузарлагдаж байх үеийнхээс ч дээр байхгүй байх байсан.$B$BHorde-д туслах, бидний амьдралын хэв маягийг хамгаалах нь чиний үүрэг. Гэхдээ найз ба дайсанд адилхан өршөөл, энэрэл хэзээ үзүүлэх ёстойг мэдэх нь бас чиний үүрэг.$B$BҮүнийг сайн ойлго. Энэ бол шинэ Horde, чөтгөрөөс гаралтай, чөлөөт хүсэлгүй арми биш." }
G.texts[#G.texts+1] = { p="listencloselytowhatyouaretoldanddonotqui", s="ngleaderinanywayican", t="Хэлж байгааг сайтар сонс, хурдан бүү итгэ, бүү үл итгэ. Учир нь найзууд ч гэсэн өөрсдийн зорилгод үйлчилдэг, $c.$B$BБидний агуу Warchief үүнийг мэддэг, мөн Horde дотор түүнийг дотроос нь устгах эсвэл хяналтдаа авах хүсэлгүй warlock-ууд байдгийг батлахын тулд би манай залуу удирдагчид чадах бүхнээрээ туслахаар сайн дураараа зөвшөөрсөн." }
G.texts[#G.texts+1] = { p="greetings", s="itieswithoutquestion", t="Мэндчилье, $c. Чамайг Nighthaven-д, мөн Moonglade бүхэлд нь тавтай морилно. Cenarion Circle байгалийн эрх мэдэл, зарлигийг хүндэтгэдэг бүх оршихуйг угтан авдаг.$B$BЭнд байх хугацаандаа бүх зүйлд тэнцвэрийг хадгалахаа мартуузай. Эмх замбараагүй байдлыг энд хүлээн зөвшөөрдөггүй бөгөөд манай харуулууд бүх дайсагналыг асуулгүйгээр зогсоохоор сургагдсан." }
