G.texts[#G.texts+1] = { p="greetingsyoungoneandwelcometothunderbluf", s="doingsohonoryourself", t="Мэндчилье, залуу минь, Thunder Bluff-д тавтай морил. Чи энд дэлхийн ачаа дарамтаас аюулгүй хоргодох газар олно. Horde-ийн бүх оршин суугчдыг энд угтан авна.$B$BОдоо болон өнгөрсөн үеийн сүнснүүд энэ ариун газарт амилдаг, найз минь. Тэднийг хүндэл, ингэснээр өөрийгөө хүндэл." }
G.texts[#G.texts+1] = { p="ayeyouthereifyouwanttoearntherespectofth", s="nitionofthedarkspear", t="Хөөе, чи! Хэрэв Darkspear-ийн хүндэтгэлийг хүртэхийг хүсвэл эхлээд хэрэгцээтэй хүмүүст үнэт нөөцөөс хандивлаж эхэлж болно! Даавуу, боолт модон дээр ургадаггүй гэдгийг мэд.$B$BАдал явдлаар олсон янз бүрийн даавууны хэсгийг мөнгө болгохоосоо илүү хандивла! Ингэвэл чи Darkspear-ийн хүлээн зөвшөөрөлтийг олно!" }
G.texts[#G.texts+1] = { p="inthesetryingtimesasimpledonationofcloth", s="forthehorde", t="Ийм хүнд хэцүү цаг үед энгийн даавууны хандив бидэнээс бага азтай хүмүүст ихээхэн тус болно. Даавуу нь хувцас, боолт хийхэд маш их хэрэгтэй - хоёулаа дайны хүчин чармайлтад чухал!$B$BХэрэв чи Orgrimmar-ын orc-уудад даавууны хэсэг хандивлахыг сонирхож байвал би баяртайгаар хүлээн авч, чамд зохих хүлээн зөвшөөрөлт олгохыг хангана.$B$BHorde-ийн төлөө!" }
G.texts[#G.texts+1] = { p="youthereitisinyourbestinteresttoaidthefo", s="idwillnotgounnoticed", t="Чи... эдгээр хүнд хэцүү цаг үед Forsaken-д туслах нь чиний ашиг сонирхолд нийцнэ. Сайн сонс, учир нь би давтаж хэлэх дургүй.$B$BБид одоогоор даавууны хүнд хомсдолд орсон байна. Боолт, энгийн даавуу багасч байгаа бөгөөд буурсан нөөцийг дэмжихийн тулд хандив авч байна. Чи санхүүгийн нөхөн олговор авахгүй - хандив гэдэг нь тэр - гэхдээ чиний тусламж анзаарагдахгүй өнгөрөхгүй." }
G.texts[#G.texts+1] = { p="hail", s="ywhereinhelpingusout", t="Мэндчилье, $g ах : эгч;... Хэрэв болох юм бол би чамаас хэсэг хугацаа авмаар байна.$B$BБид tauren-ууд эх орноо байгуулахдаа олон сорилт, зовлон туулсан. Одоо бид даавууны хүнд хомсдолд орсон байна. Хэрэв чамд илүүдэх материал байвал хандивлаж өгнө үү. Бидэнд тусалснаар чи хаа сайгүй tauren-уудын талархлыг хүртэх нь лавтай!" }
